#include <iostream>

bool validItem(long long price, long long quantity) {
    return price >= 0 && price <= 1000 && quantity >= 0 && quantity <= 1000;
}

long long itemCost(long long price, long long quantity) {
    return price * quantity;
}

long long discountSaving(long long subtotal, int percent) {
    return subtotal * percent / 100;
}

int main() {
    int n, discount;
    if (!(std::cin >> n >> discount) || n < 0 || n > 20 || discount < 0 || discount > 100) {
        std::cout << "invalid\n";
        return 0;
    }
    long long subtotal = 0;
    for (int i = 0; i < n; ++i) {
        long long price, quantity;
        if (!(std::cin >> price >> quantity) || !validItem(price, quantity)) {
            std::cout << "invalid\n";
            return 0;
        }
        subtotal += itemCost(price, quantity);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }
    long long saving = discountSaving(subtotal, discount);
    std::cout << subtotal << ' ' << saving << ' ' << subtotal - saving << '\n';
}
